diff --git a/apps/web/src/lib/api.test.ts b/apps/web/src/lib/api.test.ts
index 96652a6..7528960 100644
--- a/apps/web/src/lib/api.test.ts
+++ b/apps/web/src/lib/api.test.ts
@@ -30,6 +30,7 @@ beforeEach(() => {
 });

 afterEach(() => {
+  vi.restoreAllMocks();
   vi.unstubAllGlobals();
   fetchMock.mockReset();
   document.cookie = 'carehub_csrf=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/';
@@ -63,6 +64,25 @@ describe('api', () => {
     expect(headers.get('X-CSRF-Token')).toBe('abc/def==');
   });

+  it('sends the __Host- CSRF cookie, which the server sets over HTTPS', async () => {
+    // jsdom runs on http, where browsers refuse __Host- cookies, so the cookie string is stubbed.
+    vi.spyOn(document, 'cookie', 'get').mockReturnValue(
+      'carehub_csrf=plain-token; __Host-carehub_csrf=host%2Ftoken',
+    );
+    fetchMock.mockImplementation(async () => new Response(null, { status: 204 }));
+
+    await api.post('/api/pages/page-1/restore');
+    expect(lastRequest().headers.get('X-CSRF-Token')).toBe('host/token');
+  });
+
+  it('sends a CSRF cookie with broken percent-encoding as it is', async () => {
+    document.cookie = 'carehub_csrf=abc%E0%A4%A; path=/';
+    fetchMock.mockImplementation(async () => new Response(null, { status: 204 }));
+
+    await api.post('/api/pages/page-1/restore');
+    expect(lastRequest().headers.get('X-CSRF-Token')).toBe('abc%E0%A4%A');
+  });
+
   it('uses the right method for put, patch and delete, and returns undefined without a body', async () => {
     document.cookie = 'carehub_csrf=token-1; path=/';
     fetchMock.mockImplementation(async () => new Response(null, { status: 204 }));
diff --git a/apps/web/src/lib/api.ts b/apps/web/src/lib/api.ts
index b296f63..278d452 100644
--- a/apps/web/src/lib/api.ts
+++ b/apps/web/src/lib/api.ts
@@ -1,3 +1,4 @@
+import { readCsrfToken } from '@carehub/shared';
 import type { z } from 'zod';

 /** A failed API call. Status 0 with code 'offline' means Care Hub couldn't be reached. */
@@ -37,9 +38,16 @@ const CODES: Record<number, string> = {
   429: 'rate_limited',
 };

+// `__Host-carehub_csrf` over HTTPS, `carehub_csrf` on a plain-HTTP development server. A value with
+// broken percent-encoding is sent as it is.
 function csrfToken(): string | undefined {
-  const value = /(?:^|;\s*)carehub_csrf=([^;]*)/.exec(document.cookie)?.[1];
-  return value ? decodeURIComponent(value) : undefined;
+  const value = readCsrfToken(document.cookie);
+  if (!value) return undefined;
+  try {
+    return decodeURIComponent(value);
+  } catch {
+    return value;
+  }
 }

 async function request<T, S extends Schema>(

